// Turns an event from gulf-leads into a short Telegram message (plain text, so nothing from the web can inject formatting).
const e = $input.first().json.body || {};
const d = e.data || {};
const link = e.dashboard ? '\n' + e.dashboard : '';
const dash = (v) => (v ? v : '-');
const lines = {
  'lead.qualified': () => `🔥 عميل مؤهل: ${d.company}\n${d.summary}\nالاحتياج: ${dash(d.need)}\nالتوقيت: ${dash(d.timeline)}\nالتواصل: ${dash(d.person)} ${dash(d.email)} ${d.phone || ''}\nالخطوة: ${dash(d.nextStep)}${link}`,
  'lead.needs_human': () => `🙋 محادثة بحاجة لك (${d.reason}): ${d.company}\n${d.summary}${link}`,
  'proposal.ready': () => `📝 عرض مخصص جاهز لـ ${d.company}، ينتظر موافقتك${link}`,
  'reply.pending': () => `✉️ رد من المساعد ينتظر موافقتك: ${d.company}${link}`,
  'sending.paused': () => `⛔ الإرسال توقف تلقائياً: ${d.reason}${link}`,
  'lead.unsubscribed': () => `🚫 ${d.company} طلب التوقف (${d.reason}). تم حظره.`,
  'lead.bounced': () => `⚠️ إيميل مرتد: ${d.company}. تم إيقافه.`,
  'discovery.done': () => `🔎 البحث التلقائي: أُضيفت ${d.added} شركة\n` + (d.targets || []).map((t) => `• ${t.label}: +${t.added}${t.error ? ' (' + t.error + ')' : ''}`).join('\n') + link,
  'daily.summary': () => `📊 ملخص اليوم ${d.date}\nمرسلة ${d.sent} · ردود ${d.replies} · مؤهلون ${d.qualified}\nبانتظار موافقتك ${d.waitingApproval} · جاهزون لك ${d.openHandoffs}${link}`,
  'test': () => '✅ اختبار الاتصال بين gulf-leads و n8n نجح',
};
const make = lines[e.type];
if (!make) return [];
return [{ json: { text: make(), type: e.type } }];
